public static function initLogger(): void
  {
    static $loggerSet = false;

    if ($loggerSet) {
      return;
    }

    // Register a custom log file for com_[[[component]]]
    \Joomla\CMS\Log\Log::addLogger(
      [
        'text_file' => '[[[component]]].php', // File: administrator/logs/.php
        'extension' => 'com_[[[component]]]',          // Prefix inside the log file
        'text_entry_format' => '{DATETIME} {PRIORITY} {CATEGORY} {MESSAGE}'
      ],
      \Joomla\CMS\Log\Log::ALL,                // log all levels: DEBUG, INFO, WARNING, ERROR
      ['com_[[[component]]]']          // Only log entries with this category
    );

    $loggerSet = true;
  }

  /**
     * Example wrapper for error logging.
     */

  public static function logError(string $message, array $context = []): void
  {
    self::initLogger();

    $fullMessage = $message;

    if (!empty($context)) {
      $fullMessage .= ' | Context: ' . json_encode($context, JSON_UNESCAPED_SLASHES);
    }

    \Joomla\CMS\Log\Log::add($fullMessage, \Joomla\CMS\Log\Log::ERROR, 'com_[[[component]]]');
  }
